registerCombo({
  comboId: 3129,
  members: ["Fog_Dew_Sword_LT", "Sharp_Wind_Sword"],
  onActive(ctx) {
    let $sum, $a, $b, $g;
    $sum = ctx.getequiprefinerycnt("EQI_HAND_R") + ctx.getequiprefinerycnt("EQI_HAND_L");
    ctx.bonus("bBaseAtk", 15 * ($sum / 3));
    ctx.bonus("bAtkRate", 4 * ($sum / 5));
    if (ctx.getParam("BaseLevel") >= 210) {
      ctx.bonus("bPAtk", 1);
      ctx.bonus("bPow", 2);
    }
    if ($sum >= 14) {
      ctx.bonus2("bSkillCooldown", "KO_JYUMONJIKIRI", -2000);
      ctx.bonus2("bSkillAtk", "KO_JYUMONJIKIRI", 35);
      if ($sum >= 16) {
        $a = ctx.getskilllv("OB_ZANGETSU");
        $b = ctx.getskilllv("KG_KAGEHUMI");
        if ($a > $b) {
          ctx.skill("OB_ZANGETSU", $a);
        } else {
          ctx.skill("KG_KAGEHUMI", $b);
        }
        ctx.bonus2("bAddEle", "Ele_All", 15);
        if ($sum >= 18) {
          ctx.bonus2("bSkillAtk", "KO_JYUMONJIKIRI", 25);
          if ($sum >= 20) {
            ctx.bonus2("bAddSize", "Size_All", 15);
          }
        }
      }
    }
    if (ctx.getequipid("EQI_HAND_R") === 510060) {
      $g = ctx.getenchantgrade("EQI_HAND_R");
    } else {
      $g = ctx.getenchantgrade("EQI_HAND_L");
    }
    if ($g >= "ENCHANTGRADE_D") {
      ctx.bonus("bAtkRate", 3);
      if ($g >= "ENCHANTGRADE_C") {
        ctx.bonus("bLongAtkRate", 15);
        ctx.bonus("bPAtk", 1);
        if ($g >= "ENCHANTGRADE_B") {
          ctx.bonus("bPAtk", 2);
          ctx.bonus("bPow", 3);
        }
      }
    }

  },
});

