registerCombo({
  comboId: 3497,
  members: ["Ring_Of_Brave", "ShoesOfHero", "Veteran_Hammer"],
  onActive(ctx) {
    let $r;
    $r = ctx.getequiprefinerycnt("EQI_HAND_R");
    ctx.bonus2("bCriticalAddRace", "RC_Undead", 50);
    ctx.bonus2("bCriticalAddRace", "RC_Demon", 50);
    ctx.bonus2("bCriticalAddRace", "RC_DemiHuman", 50);
    ctx.bonus5("bAutoSpell", "CR_HOLYCROSS", ctx.getskilllv("CR_HOLYCROSS"), 20, "BF_WEAPON" | "BF_MAGIC", 1);
    ctx.bonus5("bAutoSpell", "AB_DUPLELIGHT", ctx.getskilllv("AB_DUPLELIGHT"), 20, "BF_WEAPON" | "BF_MAGIC", 1);
    ctx.autobonus2("{ bonus3 bAutoSpellWhenHit,\"NPC_HELLJUDGEMENT\",3,1000; }", 20, 5000, "BF_WEAPON", "{ active_transform 1871,5000; }");
    if ($r >= 7) {
      ctx.bonus("bAtkRate", 5);
      ctx.bonus("bMatkRate", 5);
      ctx.bonus2("bSkillAtk", "CR_HOLYCROSS", 50);
    }
    if ($r >= 9) {
      ctx.bonus("bAtkRate", 15);
      ctx.bonus("bMatkRate", 15);
      ctx.bonus2("bSkillAtk", "CR_HOLYCROSS", 100);
    }

  },
});

