registerCombo({
  comboId: 3499,
  members: ["ShoesOfHero", "Veteran_Axe"],
  onActive(ctx) {
    if (ctx.getskilllv("BS_DAGGER") === 3) {
      ctx.bonus("bBaseAtk", 10);
    }
    if (ctx.getskilllv("BS_SWORD") === 3) {
      ctx.bonus("bBaseAtk", 10);
    }
    if (ctx.getskilllv("BS_TWOHANDSWORD") === 3) {
      ctx.bonus("bBaseAtk", 10);
    }
    if (ctx.getskilllv("BS_KNUCKLE") === 3) {
      ctx.bonus("bBaseAtk", 10);
    }
    if (ctx.getskilllv("BS_SPEAR") === 3) {
      ctx.bonus("bBaseAtk", 10);
    }
    if (ctx.getskilllv("BS_AXE") === 3) {
      ctx.bonus("bBaseAtk", 10);
    }
    if (ctx.getskilllv("BS_MACE") === 3) {
      ctx.bonus("bBaseAtk", 10);
    }
    ctx.bonus2("bSkillCooldown", "NC_AXETORNADO", -200 * ctx.getskilllv("NC_RESEARCHFE"));

  },
});

